\" | \\"administratif\\" | \\"litige\\" | \\"facturation\\" | \\"spam\\",\\n  \\"urgent\\": true ou false,\\n  \\"resume\\": \\"résumé en 2-3 lignes maximum\\",\\n  \\"auto_envoi_possible\\": true ou false,\\n  \\"reponse_requise\\": true ou false\\n}\\n\\nCatégories (avec exemples) :\\n- offre_fournisseur : devis, propositions commerciales ou catalogues reçus d'un fournisseur. Ex : \\"Devis panneaux MDF - validité 30 jours\\"\\n- confirmation_commande : accusés de réception ou confirmations d'une commande déjà passée à un fournisseur. Ex : \\"Confirmation de votre commande n°4521\\"\\n- prospects : demandes d'information ou de devis de particuliers/entreprises intéressés par nos services. Ex : \\"Devis pour cuisine sur mesure\\"\\n- suivi_client : échanges avec des clients déjà engagés sur un projet en cours. Ex : \\"Où en est mon meuble ?\\"\\n- administratif : courriers officiels, banque, assurance, impôts, RH. Ex : \\"Relevé bancaire disponible\\"\\n- litige : réclamation, mise en demeure, mention d'avocat/tribunal, forte insatisfaction client. TOUJOURS urgent=true et auto_envoi_possible=false.\\n- facturation : factures reçues ou envoyées, relances de paiement. Ex : \\"Facture n°2026-045\\"\\n- spam : newsletters, publicités, phishing évident, démarchage commercial non sollicité sans rapport avec l'activité.\\n\\nRègles d'urgence :\\n- Ne pas se fier au mot \\"urgent\\" dans le sujet s'il n'est pas justifié par le contenu réel (une simple question commerciale n'est pas urgente même si le sujet dit \\"urgent\\").\\n- Est urgent : litige (toujours), délai serré explicite (\\"réponse avant demain\\"), problème bloquant sur un chantier en cours, client insatisfait qui réclame.\\n\\nRègles auto_envoi_possible :\\n- true UNIQUEMENT pour : accusé de réception simple sans action requise, confirmation de rdv déjà validée, confirmation_commande (accusé fournisseur).\\n- false pour tout le reste, en particulier : offre_fournisseur, devis, facture, litige, toute demande nécessitant une réponse personnalisée ou une décision métier.\\n\\nRègles reponse_requise :\\n- true si l'expéditeur attend une vraie réponse rédigée de l'entreprise : question, demande de devis ou de prix, demande de rendez-vous ou de disponibilité, relance, réclamation, proposition à accepter ou refuser.\\n- false pour : spam, notifications et mails automatiques (y compris les réponses automatiques d'absence), accusés de réception et confirmations sans question, factures et relevés sans question, newsletters, mails reçus seulement en copie pour information.\\n\\nLe résumé doit être factuel et concis, sans reformuler tout l'email.\\nHuman: Voici un email à analyser :\\nExpéditeur : \\"Anne Charlotte (Support)\\" <info@lafabriquedespieds.com>\\nSujet : Re: [La Fabrique des Pieds] Message d'un client\\nContenu : ----------------------------------------------\\n\\nMise à jour par : Anne Charlotte, 19 oct. 2026, 13:14 UTC+2\\n\\nBonjour,\\n\\nMerci pour votre commande :)\\n\\nElle est actuellement en cours de fabrication, le délai est de 4 semaines + 48/72h de livraison.\\n\\nVous devriez recevoir votre commande courant de la semaine 45.\\n\\nBelle journée,\\n ![](https://aide.mobeventpro.com/attachments/token/TD4PEWjzgZEFSWQCltw0EmCy3/?name=Anne-Charlotte.png)\\n\\n----------------------------------------------\\n\\nMise à jour par : Contact, 16 oct. 2026, 17:54 UTC+2\\n\\n  ![](https://cefgbcj.r.af.d.sendibt2.com/tr/op/-gt54Xz-mWv5Gxs_lWitMQ_SLFeLIV8OtUX0e5SOQ7drhY7fQpbGxM4lSOjoG0HrCpScCBFJ9czv4Te2u_WXG9ATCEVWlgYLFFx08VC-7W0dGfIL7a56y-H-XqlycXwUkaAwhJNH-tV1eozDTlfcVolFirgAcEi4oCutpBPGXj0FnSmFfbkIl1oHJmRUALJr0usAwgHt1dmvekOIEmDl3JkOR43yMs8nMA34)\\n\\n \\n\\n  ![](https://aide.mobeventpro.com/attachments/token/x42Aj2c6Yi8x7e7aelSXwvVIf/?name=logo_mail-1718606296.jpg)\\n\\nBonjour,\\n\\nMessage d'un client\\n\\nVous avez reçu un nouveau message concernant la commande ayant pour référence : 000061307.\\n\\nClient : Valentin Caufriez (contact@ebanista.fr)\\n\\nMessage du client :\\n\\nBonjour,\\nPouvez vous m'indiquer un délai pour cette fabrication?\\nCet élément bloque mon chantier actuel. J'en aurais besoin rapidement.\\nCordialement,\\nCaufriez Valentin\\nSociete Ebanista\\n\\nLa Fabrique des Pieds\\n\\n--------------------------------\\nCet e-mail provient de Lafabriquedespieds.\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n[GP6NPP-5M443]\\n",{"lc":1,"type":"267","id":"268"},"claude-sonnet-4-6","https://api.anthropic.com",{},{"fetchOptions":"269"},{"lc":1,"type":"267","id":"270"},{"address":"271","name":"272"},{"address":"202","name":"203"},{"address":"202","name":"273"},["274"],"secret",["275"],{},["275"],"contact@ebanista.fr","Contact","Support",{"text":"195"},"ANTHROPIC_API_KEY"]	9ae720d1-6695-40df-bb06-2ffc14b6dde8
459	{"id":"lfynCIkeDPS6hIXu","name":"Digest quotidien 7h - v.caufriez","nodes":[{"parameters":{"notice":"","rule":{"interval":[{"field":"cronExpression","notice":"","expression":"0 7 * * *"}]},"skipDurableScheduler":false},"type":"n8n-nodes-base.scheduleTrigger","typeVersion":1.2,"position":[0,0],"id":"d1a1b111-0000-4000-8000-000000000001","name":"Schedule Trigger 7h"},{"parameters":{"curlImport":"","method":"GET","url":"http://localhost:5678/api/v1/data-tables/IgT0r6Yg3ZtzMWNR/rows","authentication":"genericCredentialType","genericAuthType":"httpHeaderAuth","provideSslCertificates":false,"sendQuery":true,"specifyQuery":"keypair","queryParameters":{"parameters":[{"name":"limit","value":"250"}]},"sendHeaders":false,"sendBody":false,"options":{},"infoMessage":""},"type":"n8n-nodes-base.httpRequest","typeVersion":4.2,"position":[224,0],"id":"d1a1b111-0000-4000-8000-000000000002","name":"Get digest_mails rows","credentials":{"httpHeaderAuth":{"id":"Lfuh7XFXewkeDjJe","name":"n8n API Key (interne)"}}},{"parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"const rows = $input.first().json.data || [];\\n\\nconst LIMIT = 3800; // limite Telegram : 4096 caractères par message\\nconst LABELS = { 'v.caufriez': 'v.caufriez@ebanista.fr', 'contact': 'contact@ebanista.fr', 'comptabilite': 'comptabilite@ebanista.fr' };\\nconst ORDER = ['v.caufriez', 'contact', 'comptabilite'];\\n\\nif (rows.length === 0) {\\n  return [{ json: { text: \\"📋 Digest quotidien EBANISTA\\\\n\\\\nAucun mail à traiter aujourd'hui.\\", count: 0 } }];\\n}\\n\\n// regroupement par boîte (les anciennes lignes sans boîte viennent de v.caufriez)\\nconst groups = {};\\nfor (const r of rows) {\\n  const box = r.boite || 'v.caufriez';\\n  (groups[box] = groups[box] || []).push(r);\\n}\\nconst boxes = [...ORDER.filter(b => groups[b]), ...Object.keys(groups).filter(b => !ORDER.includes(b))];\\n\\n// un bloc de texte par boîte, puis découpage en messages de taille raisonnable\\nconst blocks = [];\\nfor (const box of boxes) {\\n  const list = groups[box];\\n  blocks.push(`📥 ${LABELS[box] || box} (${list.length})`);\\n  for (const r of list) {\\n    blocks.push(`• [${r.categorie}] ${r.expediteur}\\\\n  ${r.resume}`);\\n  }\\n}\\n\\nconst header = `📋 Digest quotidien EBANISTA — ${rows.length} mail(s)`;\\nconst chunks = [];\\nlet current = header;\\nfor (const b of blocks) {\\n  const next = current + '\\\\n\\\\n' + b;\\n  if (next.length > LIMIT && current !== header) {\\n    chunks.push(current);\\n    current = '(suite)\\\\n\\\\n' + b;\\n  } else {\\n    current = next;\\n  }\\n}\\nchunks.push(current);\\n\\nreturn chunks.map(text => ({ json: { text, count: rows.length } }));\\n","notice":""},"type":"n8n-nodes-base.code","typeVersion":2,"position":[448,0],"id":"d1a1b111-0000-4000-8000-000000000003","name":"Build digest text"},{"parameters":{"resource":"message","operation":"sendMessage","chatId":"8848139246","text":"={{ (($json.text)).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;') }}","replyMarkup":"none","additionalFields":{"appendAttribution":false,"parse_mode":"HTML"}},"type":"n8n-nodes-base.telegram","typeVersion":1.2,"position":[672,0],"id":"d1a1b111-0000-4000-8000-000000000004","name":"Send digest to Telegram","credentials":{"telegramApi":{"id":"duvmoy6UkxnbnBdr","name":"Ebanista Mails"}},"webhookId":"363c01d7-51fe-4fad-9eaa-5b88407a022d"},{"parameters":{"curlImport":"","method":"DELETE","url":"http://localhost:5678/api/v1/data-tables/IgT0r6Yg3ZtzMWNR/rows/clear","authentication":"genericCredentialType","genericAuthType":"httpHeaderAuth","provideSslCertificates":false,"sendQuery":false,"sendHeaders":false,"sendBody":false,"options":{},"infoMessage":""},"type":"n8n-nodes-base.httpRequest","typeVersion":4.2,"position":[896,0],"id":"d1a1b111-0000-4000-8000-000000000005","name":"Clear digest_mails table","credentials":{"httpHeaderAuth":{"id":"Lfuh7XFXewkeDjJe","name":"n8n API Key (interne)"}}}],"connections":{"Schedule Trigger 7h":{"main