],"id":"f1a1b111-0000-4000-8000-000000000030","name":"Facture à transférer ?"},{"parameters":{"authentication":"coreImapAccount","resource":"email","operation":"downloadAttachment","mailboxPath":{"__rl":true,"mode":"path","value":"INBOX"},"emailUid":"={{ $('Email Trigger (IMAP)').item.json.attributes.uid }}","allAttachments":true,"includeInlineAttachments":false},"type":"n8n-nodes-imap.imap","typeVersion":1,"position":[1792,-304],"id":"f1a1b111-0000-4000-8000-000000000031","name":"Télécharger pièces jointes","credentials":{"imap":{"id":"nFnyy1qJ60BZTKsw","name":"IMAP - contact@ebanista.fr"}}},{"parameters":{"resource":"email","operation":"send","fromEmail":"v.caufriez@ebanista.fr","toEmail":"comptabilite@ebanista.fr","subject":"=TR: {{ $('Email Trigger (IMAP)').item.json.subject }}","emailFormat":"text","text":"=Facture reçue sur contact@ebanista.fr et transmise automatiquement.\\n\\nDe : {{ $('Email Trigger (IMAP)').item.json.from.text }}\\nDate : {{ $('Email Trigger (IMAP)').item.json.date }}\\nObjet : {{ $('Email Trigger (IMAP)').item.json.subject }}\\n\\nRésumé : {{ $('Filtrer spam').item.json.resume }}\\n\\n---------- Message d'origine ----------\\n{{ $('Email Trigger (IMAP)').item.json.text || '(message sans texte, voir pièces jointes)' }}","options":{"appendAttribution":false,"fileAttachments":"={{ Object.keys($binary || {}).join(',') }}","replyTo":"={{ $('Email Trigger (IMAP)').item.json.from.text }}"}},"type":"n8n-nodes-base.emailSend","typeVersion":2.1,"position":[2016,-304],"id":"f1a1b111-0000-4000-8000-000000000032","name":"Transférer à la comptabilité","credentials":{"smtp":{"id":"HpY9yQWKI4eEr1b8","name":"SMTP - v.caufriez@ebanista.fr"}},"webhookId":"416c2beb-48fa-4694-b193-9d0959cb1765"},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":3},"conditions":[{"id":"d2000000-0000-4000-8000-00000000f001","leftValue":"={{ $json.reponse_requise }}","rightValue":"","operator":{"type":"boolean","opera