4","from_address":"200","from_name":"201","subject":"182","message_id":"187","extrait":"180","resume":"195","categorie":"194","uid":"202","id":82,"createdAt":"203","updatedAt":"203"},{"item":0},{"categorie":"194","urgent":false,"resume":"195","auto_envoi_possible":false,"reponse_requise":false,"targetFolder":"204","markAsRead":false},{"item":0},{"item":0},{"path":"205","destination":"204","uidValidity":"206","uidMap":"207"},{"item":0},{"return-path":"208","delivered-to":"209","received":"210","authentication-results":"211","dkim-signature":"212","x-me-helo":"213","x-me-auth":"214","x-me-date":"215","x-me-ip":"216","from":"217","content-type":"218","mime-version":"219","subject":"220","date":"221","references":"222","to":"223","in-reply-to":"224","message-id":"225","x-mailer":"226","x-spam-score":"227","x-spam-detail":"228","x-spam-verdict":"229","x-spam-state":"230","x-infomaniak-type":"231","x-infomaniak-dcc-fuz1":"232","x-infomaniak-dcc-fuz2":"233","x-infomaniak-pyzor-hash":"234","x-infomaniak-spam":"235","x-infomaniak-cause":"236","x-rspamd-queue-id":"237","x-rspamd-server":"238","x-rspamd-action":"239","x-spamd-result":"240"},"<html aria-label=\\"message body\\"><head><meta http-equiv=\\"content-type\\" content=\\"text/html; charset=utf-8\\"></head><body style=\\"overflow-wrap: break-word; -webkit-nbsp-mode: space; line-break: after-white-space;\\"><span style=\\"font-size: 14px;\\">Bonjour,</span><div><span style=\\"font-size: 14px;\\">Merci pour ces éléments.</span></div><div><span style=\\"font-size: 14px;\\">Je patienterai jusqu’en fin de semaine.</span></div><div><span style=\\"font-size: 14px;\\">Je vous souhaite une bonne journée.</span></div><div><span style=\\"font-size: 14px;\\">Cordialement.</span></div><div><span style=\\"font-size: 14px;\\">JM.MURY<br id=\\"lineBreakAtBeginningOfMessage\\"></span><div><br><blockquote type=\\"cite\\"><div>Le 13 oct. 2026 à 14:21, Ebanista &lt;contact@ebanista.fr&gt; a écrit :</div><br class=\\"Apple-interchange-newline\\"><div><div>Bonjour M. Mury,<br><br>Nous procédons actuellement aux modifications et reviendrons vers vous d'ici la fin de semaine avec le devis corrigé ainsi que le plan réajusté.<br><br>Concernant l'acompte, celui-ci sera indiqué sur l'offre.<br><br>Merci d'avance pour votre retour.<br><br>Cordialement,<br><br>L'équipe Ebanista<br><br><br>Le 12 octobre 2026 à 21:03, MURY Jean-Marc &lt;jean-marc.mury@orange.fr&gt; a écrit :<br><blockquote type=\\"cite\\">Bonsoir Valentin,<br>Je reviens vers vous car je n’ai pas eu de retour suite à mon mail du 30/09.<br>Je suis en attente du devis corrigé (plan et tarification).<br>En ce qui concerne notre partie pour la libération de l’espace de travail tout est OK, vous pouvez intervenir dès maintenant quand vous le souhaitez.<br>Pour cela, avez-vous besoin d’un acompte ?<br>Si oui de combien ?<br>Je vous souhaite une bonne soirée et attend votre retour.<br>Cordialement.<br>JM.MURY<br><br><br><br><blockquote type=\\"cite\\">Début du message réexpédié :<br><br>De: MURY Jean-Marc &lt;jean-marc.mury@orange.fr&gt;<br>Objet: INFOS COMPLEMENTAIRES DOSSIER MURY<br>Date: 30 septembre 2026 à 09:52:54 UTC+2<br>À: Ebanista &lt;contact@ebanista.fr&gt;<br><br>Bonjour Valentin,<br>Suite à notre entrevue du Vendredi 11 Septembre vous deviez me faire parvenir par retour de mail les correctifs en ce qui concerne le projet de notre mezzanine.<br>Merci de me faire passer ces éléments sur le dimensionnel avec le plan et le devis corrigés et réajustés.<br>Bonne journée à vous.<br>Cordialement.<br>JM.MURY<br></blockquote></blockquote></div></div></blockquote></div><br></div></body></html>","Bonjour,\\nMerci pour ces éléments.\\nJe patienterai jusqu’en fin de semaine.\\nJe vous souhaite une bonne journée.\\nCordialement.\\nJM.MURY\\n\\n> Le 13 oct. 2026 à 14:21, Ebanista <contact@ebanista.fr> a écrit :\\n> \\n> Bonjour M. Mury,\\n> \\n> Nous procédons actuellement aux modifications et reviendrons vers vous d'ici la fin de semaine avec le devis corrigé ainsi que le plan réajusté.\\n> \\n> Concernant l'acompte, celui-ci sera indiqué sur l'offre.\\n> \\n> Merci d'avance pour votre retour.\\n> \\n> Cordialement,\\n> \\n> L'équipe Ebanista\\n> \\n> \\n> Le 12 octobre 2026 à 21:03, MURY Jean-Marc <jean-marc.mury@orange.fr> a écrit :\\n>> Bonsoir Valentin,\\n>> Je reviens vers vous car je n’ai pas eu de retour suite à mon mail du 30/09.\\n>> Je suis en attente du devis corrigé (plan et tarification).\\n>> En ce qui concerne notre partie pour la libération de l’espace de travail tout est OK, vous pouvez intervenir dès maintenant quand vous le souhaitez.\\n>> Pour cela, avez-vous besoin d’un acompte ?\\n>> Si oui de combien ?\\n>> Je vous souhaite une bonne soirée et attend votre retour.\\n>> Cordialement.\\n>> JM.MURY\\n>> \\n>> \\n>> \\n>>> Début du message réexpédié :\\n>>> \\n>>> De: MURY Jean-Marc <jean-marc.mury@orange.fr>\\n>>> Objet: INFOS COMPLEMENTAIRES DOSSIER MURY\\n>>> Date: 30 septembre 2026 à 09:52:54 UTC+2\\n>>> À: Ebanista <contact@ebanista.fr>\\n>>> \\n>>> Bonjour Valentin,\\n>>> Suite à notre entrevue du Vendredi 11 Septembre vous deviez me faire parvenir par retour de mail les correctifs en ce qui concerne le projet de notre mezzanine.\\n>>> Merci de me faire passer ces éléments sur le dimensionnel avec le plan et le devis corrigés et réajustés.\\n>>> Bonne journée à vous.\\n>>> Cordialement.\\n>>> JM.MURY\\n\\n","<p>Bonjour,<br/>Merci pour ces &eacute;l&eacute;ments.<br/>Je patienterai jusqu&rsquo;en fin de semaine.<br/>Je vous souhaite une bonne journ&eacute;e.<br/>Cordialement.<br/>JM.MURY</p><p>&gt; Le 13 oct. 2026 &agrave; 14:21, Ebanista &lt;<a href=\\"mailto:contact@ebanista.fr\\">contact@ebanista.fr</a>&gt; a &eacute;crit :<br/>&gt;<br/>&gt; Bonjour M. Mury,<br/>&gt;<br/>&gt; Nous proc&eacute;dons actuellement aux modifications et reviendrons vers vous d&apos;ici la fin de semaine avec le devis corrig&eacute; ainsi que le plan r&eacute;ajust&eacute;.<br/>&gt;<br/>&gt; Concernant l&apos;acom