nspan.EmailStyle17\\n\\t{mso-style-type:personal-compose;\\n\\tfont-family:\\"Aptos\\",sans-serif;\\n\\tcolor:windowtext;}\\n.MsoChpDefault\\n\\t{mso-style-type:export-only;\\n\\tfont-size:11.0pt;\\n\\tmso-fareast-language:EN-US;}\\n@page WordSection1\\n\\t{size:612.0pt 792.0pt;\\n\\tmargin:70.85pt 70.85pt 70.85pt 70.85pt;}\\ndiv.WordSection1\\n\\t{page:WordSection1;}\\n--></style><!--[if gte mso 9]><xml>\\n<o:shapedefaults v:ext=\\"edit\\" spidmax=\\"1026\\" />\\n</xml><![endif]--><!--[if gte mso 9]><xml>\\n<o:shapelayout v:ext=\\"edit\\">\\n<o:idmap v:ext=\\"edit\\" data=\\"1\\" />\\n</o:shapelayout></xml><![endif]-->\\n</head>\\n<body lang=\\"FR\\" link=\\"#467886\\" vlink=\\"#96607D\\" style=\\"word-wrap:break-word\\">\\n<div class=\\"WordSection1\\">\\n<p class=\\"MsoNormal\\">Bonjour Monsieur Caufriez,<o:p></o:p></p>\\n<p class=\\"MsoNormal\\"><o:p>&nbsp;</o:p></p>\\n<p class=\\"MsoNormal\\">Je viens de recevoir votre bilan 2026.<o:p></o:p></p>\\n<p class=\\"MsoNormal\\"><o:p>&nbsp;</o:p></p>\\n<p class=\\"MsoNormal\\">Comme chaque année, je vous propose de nous rencontrer afin de faire le point sur l'exercice écoulé et d'échanger sur l'avancement de vos projets pour l'année en cours.<o:p></o:p></p>\\n<p class=\\"MsoNormal\\">Pourriez-vous m'indiquer vos prochaines disponibilités pour planifier cet entretien ?<o:p></o:p></p>\\n<p class=\\"MsoNormal\\"><o:p>&nbsp;</o:p></p>\\n<p class=\\"MsoNormal\\">Dans l'attente de votre retour, je reste à votre disposition.<o:p></o:p></p>\\n<p class=\\"MsoNormal\\">Bien cordialement,<o:p></o:p></p>\\n<table class=\\"MsoNormalTable\\" border=\\"0\\" cellspacing=\\"0\\" cellpadding=\\"0\\" style=\\"border-collapse:collapse\\">\\n<tbody>\\n<tr style=\\"height:12.5pt\\">\\n<td nowrap=\\"\\" valign=\\"top\\" style=\\"padding:0cm 0cm 0cm 0cm;height:12.5pt\\">\\n<p class=\\"MsoNormal\\" style=\\"margin:.1pt;line-height:12.5pt\\"><span style=\\"font-family:&quot;Calibri&quot;,sans-serif;color:black;mso-ligatures:none;mso-fareast-language:FR\\">&nbsp;&nbsp;&nbsp;</span><span style=\\"font-size:12.0pt;mso-ligatures:none;mso-fareast-language:FR\\"><o:p></o:p></span></p>\\n</td>\\n</tr>\\n<tr style=\\"height:11.5pt\\">\\n<td width=\\"600\\" valign=\\"top\\" style=\\"width:450.0pt;padding:0cm 0cm 0cm 0cm;height:11.5pt\\">\\n<table class=\\"MsoNormalTable\\" border=\\"0\\" cellspacing=\\"0\\" cellpadding=\\"0\\" width=\\"600\\" style=\\"width:450.0pt;border-collapse:collapse\\">\\n<tbody>\\n<tr>\\n<td style=\\"padding:0cm 0cm 0cm 0cm\\">\\n<p class=\\"MsoNormal\\" style=\\"margin:.1pt;line-height:12.0pt\\"><i><span style=\\"font-size:10.0pt;color:#232323;mso-ligatures:none;mso-fareast-language:FR\\">Vous recevrez dans quelques jours une enquête de satisfaction par email. Votre opinion est essentielle pour\\n nous aider à améliorer nos services. Je </span></i><i><span style=\\"font-size:10.0pt;color:black;mso-ligatures:none;mso-fareast-language:FR\\">compte sur\\n</span></i><i><span style=\\"font-size:10.0pt;color:#232323;mso-ligatures:none;mso-fareast-language:FR\\">votre participation et votre précieuse contribution.</span></i><span style=\\"font-size:10.0pt;mso-ligatures:none;mso-fareast-language:FR\\"><o:p></o:p></span></p>\\n</td>\\n</tr>\\n</tbody>\\n</table>\\n</td>\\n</tr>\\n<tr style=\\"height:12.5pt\\">\\n<td nowrap=\\"\\" valign=\\"top\\" style=\\"padding:0cm 0cm 0cm 0cm;height:12.5pt\\"></td>\\n</tr>\\n<tr style=\\"height:11.5pt\\">\\n<td valign=\\"top\\" style=\\"padding:0cm 0cm 0cm 0cm;height:11.5pt\\">\\n<table class=\\"MsoNormalTable\\" border=\\"0\\" cellspacing=\\"0\\" cellpadding=\\"0\\" style=\\"border-collapse:collapse\\">\\n<tbody>\\n<tr style=\\"height:11.5pt\\">\\n<td nowrap=\\"\\" valign=\\"top\\" style=\\"padding:0cm 0cm 0cm 0cm;height:11.5pt\\">\\n<table class=\\"MsoNormalTable\\" border=\\"0\\" cellspacing=\\"0\\" cellpadding=\\"0\\" style=\\"border-collapse:collapse\\">\\n<tbody>\\n<tr>\\n<td style=\\"padding:0cm 0cm 0cm 0cm\\">\\n<p class=\\"MsoNormal\\" style=\\"margin