imated":false},["92"],{"previousNode":"88","previousNodeOutput":0,"previousNodeRun":0},["93"],{"previousNode":"94","previousNodeOutput":0,"previousNodeRun":0},["95"],{"node":"96","runIndex":0},["97"],"Entrée sous-workflow",["98"],"Retrouver mes réponses précédentes",["99"],"Rédiger le brouillon",["100"],["101"],"Assembler le contexte",["102"],["103"],"Composer le brouillon",["104"],"Modèle Claude (brouillon)",{"json":"105","index":0,"pairedItem":"106"},{"json":"107","pairedItem":"108"},{"json":"109","pairedItem":"110"},{"json":"111"},{"json":"112"},{"json":"113","pairedItem":"114"},{"json":"115","pairedItem":"116"},{"json":"117","pairedItem":"118"},{"from_address":"119","from_name":"120","subject":"121","text":"122","date":"123","message_id":"124","resume":"125","categorie":"126"},{"item":0},{"seq":598,"uid":605,"modseq":"127","bodyStructure":"128","envelope":"129","id":"130","mailboxPath":"131","textContent":"132"},{"item":0},{"prompt":"133","historyCount":1},{"item":0},{"response":"134","tokenUsage":"135"},{"messages":"136","estimatedTokens":1208,"options":"137"},{"text":"138"},{"item":0},{"rfc822":"139","subject":"140","draftPreview":"138"},{"item":0},{"destination":"141","path":"141","seq":6,"uidValidity":"142","uid":5089},{"item":0},"Mustapha.Derrar@ac-grenoble.fr","Derrar Mustapha","Stagiaire GUIRONNET Quentin","Bonjour Monsieur,  \\nPourriez-vous me remplir et me faire parvenir ce document administratif ( en pdf ou word) afin de valider la période d'essai des 45 jours. \\n\\nJe reprendrais contact avec vous pour faire un bilan de son implication et des tâches qui lui sont confiées durant son apprentissage. \\n\\nBien cordialement \\n\\n\\n \\n\\nM.DERRAR \\n\\nEnseignant en Architecture  \\n\\nLycée Professionnel Léon PAVIN - 241 Chemin du Trouillet - 07210 Chomérac \\n\\n06-66-94-98-05\\n","2026-10-19T14:05:35.000Z","<144844965320674c.6ad63fcf@ac-grenoble.fr>","Un enseignant du lycée Léon Pavin demande de remplir et retourner un document administratif pour valider la période d'essai de 45 jours du stagiaire/apprenti Quentin Guironnet.","administratif","1322",{"childNodes":"143","type":"144","parameters":"145"},{"date":"146","subject":"147","from":"148","sender":"149","replyTo":"150","to":"151","inReplyTo":"152","messageId":"153"},"c60d43f0f684a955cf5bdc9044f85ed2","Sent","Bonjour,\\r\\n\\r\\nVous trouverez en pièce jointe le document signé.\\r\\n\\r\\nBonne réception.\\r\\n\\r\\nJe vous souhaite une très belle journée.\\r\\n\\r\\nCordialement,\\r\\n\\r\\nSelina Sanchez\\r\\n\\r\\n Am 01/07/2026, 13:53, Derrar Mustapha\\r\\n<Mustapha.Derrar@ac-grenoble.fr> schrieb: \\r\\n\\r\\n> Bonjour,  \\r\\n>  Suite à notre échange de ce début d'après midi, veuillez\\r\\n> trouver ci-joint les fiches à me renvoyer signé avec le cachet de\\r\\n> votre entreprise. \\r\\n>  Je vous remercie du temps que vous nous avez accordé pour le suivi\\r\\n> d'Alizée. \\r\\n>  Bien cordialement, \\r\\n> \\r\\n>  M.DERRAR \\r\\n>  06-66-94-98-05\\r\\n\\r\\n","MAIL REÇU\\nDe : Derrar Mustapha <Mustapha.Derrar@ac-grenoble.fr>\\nObjet : Stagiaire GUIRONNET Quentin\\nDate : 2026-10-19T14:05:35.000Z\\nRésumé (assistant de tri) : Un enseignant du lycée Léon Pavin demande de remplir et retourner un document administratif pour valider la période d'essai de 45 jours du stagiaire/apprenti Quentin Guironnet.\\n\\nContenu :\\nBonjour Monsieur,  \\nPourriez-vous me remplir et me faire parvenir ce document administratif ( en pdf ou word) afin de valider la période d'essai des 45 jours. \\n\\nJe reprendrais contact avec vous pour faire un bilan de son implication et des tâches qui lui sont confiées durant son apprentissage. \\n\\nBien cordialement \\n\\n\\n \\n\\nM.DERRAR \\n\\nEnseignant en Architecture  \\n\\nLycée Professionnel Léon PAVIN - 241 Chemin du Trouillet - 07210 Chomérac \\n\\n06-66-94-98-05\\n\\nHISTORIQUE : tes dernières réponses à cet interlocuteur (de la plus récente à la plus ancienne)\\n--- Échange 1 (2026-07-07, objet : Re: Fiche Moulet Alizée) ---\\nBonjour,\\n\\nVous trouverez en pièce jointe le document signé.\\n\\nBonne réception.\\n\\nJe vous souhaite une très belle journée.\\n\\nCordialement,\\n\\nSelina Sanchez\\n\\n Am 01/07/2026, 13:53, Derrar Mustapha\\n<Mustapha.Derrar@ac-grenoble.fr> schrieb:\\n\\nRédige le brouillon de réponse.",{"generations":"154"},{"completionTokens":145,"promptTokens":1623,"totalTokens":1768},["155"],{"anthropic_api_key":"156","model":"157","anthropic_api_url":"158","max_tokens":16384,"invocation_kwargs":"159","client_options":"160","streaming":false,"temperature":0.4,"api_key":"161"},"Bonjour Monsieur Derrar,\\n\\nMerci pour votre message concernant Quentin Guironnet.\\n\\nVous trouverez en pièce jointe le document administratif complété pour valider la période d'essai des 45 jours.\\n\\n[À COMPLÉTER : vérifier que le document est bien joint et signé avant envoi]\\n\\nNous restons disponibles pour le bilan que vous souhaitez réaliser sur son implication et les tâches qui lui sont confiées.\\n\\nBien cordialement,\\n[À COMPLÉTER : signature]","From: Ebanista <contact@ebanista.fr>\\r\\nTo: Derrar Mustapha <Mustapha.Derrar@ac-grenoble.fr>\\r\\nSubject: Re: Stagiaire GUIRONNET Quentin\\r\\nDate: Mon, 19 Oct 2026 14:05:46 +0000\\r\\nMessage-ID: <draft-1792418746110-1bc6uaev@ebanista.fr>\\r\\nIn-Reply-To: <144844965320674c.6ad63fcf@ac-grenoble.fr>\\r\\nReferences: <144844965320674c.6ad63fcf@ac-grenoble.fr>\\r\\nMIME-Version: 1.0\\r\\nContent-Type: text/plain; charset=UTF-8\\r\\nContent-Transfer-Encoding: base64\\r\\n\\r\\nQm9uam91ciBNb25zaWV1ciBEZXJyYXIsDQoNCk1lcmNpIHBvdXIgdm90cmUgbWVzc2FnZSBjb25j\\r\\nZXJuYW50IFF1ZW50aW4gR3Vpcm9ubmV0Lg0KDQpWb3VzIHRyb3V2ZXJleiBlbiBwacOoY2Ugam9p\\r\\nbnRlIGxlIGRvY3VtZW50IGFkbWluaXN0cmF0aWYgY29tcGzDqXTDqSBwb3VyIHZhbGlkZXIgbGEg\\r\\ncMOpcmlvZGUgZCdlc3NhaSBkZXMgNDUgam91cnMuDQoNClvDgCBDT01QTMOJVEVSIDogdsOpcmlm\\r\\naWVyIHF1ZSBsZSBkb2N1bWVudCBlc3QgYmllbiBqb2ludCBldCBzaWduw6kgYXZhbnQgZW52b2ld\\r\\nDQoNCk5vdXMgcmVzdG9ucyBkaXNwb25pYmxlcyBwb3VyIGxlIGJpbGFuIHF1ZSB2b3VzIHNvdWhh\\r\\naXRleiByw6lhbGlzZXIgc3VyIHNvbiBpbXBsaWNhdGlvbiBldCBsZXMgdMOiY2hlcyBxdWkgbHVp\\r\\nIHNvbnQgY29uZmnDqWVzLg0KDQpCaWVuIGNvcmRpYWxlbWVudCwNClvDgCBDT01QTMOJVEVSIDog\\r\\nc2lnbmF0dXJlXQ0KDQoNCkxlIDE5IG9jdG9icmUgMjAyNiDDoCAxNjowNSwgRGVycmFyIE11c3Rh\\r\\ncGhhIDxNdXN0YXBoYS5EZXJyYXJAYWMtZ3Jlbm9ibGUuZnI+IGEgw6ljcml0IDoNCj4gQm9uam91\\r\\nciBNb25zaWV1ciwgIA0KPiBQb3Vycmllei12b3VzIG1lIHJlbXBsaXIgZXQgbWUgZmFpcmUgcGFy\\r\\ndmVuaXIgY2UgZG9jdW1lbnQgYWRtaW5pc3RyYXRpZiAoIGVuIHBkZiBvdSB3b3JkKSBhZmluIGRl\\r\\nIHZhbGlkZXIgbGEgcMOpcmlvZGUgZCdlc3NhaSBkZXMgNDUgam91cnMuIA0KPiANCj4gSmUgcmVw\\r\\ncmVuZHJhaXMgY29udGFjdCBhdmVjIHZvdXMgcG91ciBmYWlyZSB1biBiaWxhbiBkZSBzb24gaW1w\\r\\nbGljYXRpb24gZXQgZGVzIHTDomNoZXMgcXVpIGx1aSBzb250IGNvbmZpw6llcyBkdXJhbnQgc29u\\r\\nIGFwcHJlbnRpc3NhZ2UuIA0KPiANCj4gQmllbiBjb3JkaWFsZW1lbnQgDQo+IA0KPiANCj4gIA0K\\r\\nPiANCj4gTS5ERVJSQVIgDQo+IA0KPiBFbnNlaWduYW50IGVuIEFyY2hpdGVjdHVyZSAgDQo+IA0K\\r\\nPiBMeWPDqWUgUHJvZmVzc2lvbm5lbCBMw6lvbiBQQVZJTiAtIDI0MSBDaGVtaW4gZHUgVHJvdWls\\r\\nbGV0IC0gMDcyMTAgQ2hvbcOpcmFjIA0KPiANCj4gMDYtNjYtOTQtOTgtMDUNCg==\\r\\n","Re: Stagiaire GUIRONNET Quentin","Drafts","1732048448",["162","163"],"multipart/mixed",{"boundary":"164"},"2026-07-07T07:46:32.000Z","Re: Fiche Moulet Alizée",["165"],["166"],["167"],["168"],"<ed729861491b810c.6a451bd7@ac-grenoble.fr>","<24c7fe8f-bc74-42b4-b195-7c996dff9eec@mail.infomaniak.com>",["169"],"System: Tu rédiges des BROUILLONS de réponses d'e-mails pour la boîte administrative d'EBANISTA (menuiserie / ébénisterie sur mesure). Cette boîte sert au secrétariat, à la comptabilité, aux ressources humaines et aux échanges avec les clients et les fournisseurs. La personne qui la gère relira et modifiera chaque brouillon avant de l'envoyer : tu écris à sa place, dans son style.\\n\\nRéponds UNIQUEMENT avec le corps du message : pas d'objet, pas de commentaire, pas de guillemets, pas de balises.\\n\\nSTYLE (tiré des mails envoyés depuis cette boîte) :\\n- Vouvoiement quasi systématique, ton poli, professionnel et courtois, sans familiarité. Tutoie uniquement si l'historique de ses échanges avec cette personne montre qu'elle la tutoie.\\n- Salutation : \\"Bonjour,\\" ou \\"Bonjour Prénom,\\" ; \\"Bonjour Madame Nom,\\" / \\"Bonjour Monsieur Nom,\\" avec un interlocuteur formel. Mets un prénom ou un nom seulement si tu en es sûr.\\n- Phrases complètes et claires, paragraphes courts (3 à 8 lignes en général). Formules typiques : \\"Je reviens vers vous concernant …\\", \\"Merci pour votre retour.\\", \\"Merci beaucoup pour l'envoi de …\\", \\"Vous trouverez en pièce jointe …\\", \\"Je vous mets … en pièce jointe.\\".\\n- Demandes précises : \\"Pourriez-vous …\\", \\"Serait-il possible de …\\". Si plusieurs points, une liste à puces.\\n- Avant la fin : \\"Merci d'avance pour votre retour.\\" ou \\"Je vous remercie par avance pour votre retour.\\"\\n- Formule de fin : \\"Cordialement,\\" ou \\"Bien cordialement,\\", parfois \\"Bonne journée,\\" / \\"Belle journée,\\".\\n- Signature : écris exactement [À COMPLÉTER : signature] sur la dernière ligne, sous la formule de fin.\\n- Réclamation, litige ou retard (facture erronée, résiliation, livraison manquante) : ton ferme, calme et factuel ; rappelle les dates, références et faits qui figurent dans le mail reçu ; demande clairement ce qui est attendu et dans quel délai si le mail le permet.\\n\\nRÈGLES STRICTES :\\n- N'invente JAMAIS un montant, un nombre d'heures, une date, un délai, un numéro de contrat ou de dossier, une référence, une quantité ni un engagement. Si une information nécessaire manque, écris [À COMPLÉTER : ce qu'il faut préciser] à l'endroit voulu.\\n- Les DÉCISIONS ne sont jamais à ta charge : accepter ou refuser une offre, valider un devis, passer ou annuler une commande, payer, fixer une date, accorder un geste commercial, valider une demande d'un salarié. N'écris jamais \\"oui\\", \\"c'est d'accord\\", \\"je confirme\\" ou \\"nous validons\\" à sa place. Écris [À COMPLÉTER : décision à prendre (ce qu'il faut trancher)] ou une réponse neutre (accuser réception, demander une précision, dire que tu reviens vers l'interlocuteur).\\n- N'ajoute AUCUNE précision (références, dimensions, quantités, noms de personnes, détails de paie ou de contrat) qui n'est pas dans le mail reçu, même si elle apparaît dans l'historique : l'historique ne sert qu'à choisir le ton (tu / vous), la salutation et la formule de fin. Ne reprends jamais d'informations personnelles d'un ancien échange.\\n- Sujets sensibles (paie, ressources humaines, rupture de contrat, litiges juridiques) : reste neutre et prudent, n'engage pas l'entreprise, laisse [À COMPLÉTER] pour toute information ou décision.\\n- Réponds à toutes les questions posées dans le mail reçu, point par point si nécessaire.\\n- Écris en français, sauf si l'interlocuteur écrit dans une autre langue : réponds alors dans sa langue.\\n- Ne cite pas l'historique et ne recopie pas le mail reçu.\\nHuman: MAIL REÇU\\nDe : Derrar Mustapha <Mustapha.Derrar@ac-grenoble.fr>\\nObjet : Stagiaire GUIRONNET Quentin\\nDate : 2026-10-19T14:05:35.000Z\\nRésumé (assistant de tri) : Un enseignant du lycée Léon Pavin demande de remplir et retourner un document administratif pour valider la période d'essai de 45 jours du stagiaire/apprenti Quentin Guironnet.\\n\\nContenu :\\nBonjour Monsieur,  \\nPourriez-vous me remplir et me faire parvenir ce document administratif ( en pdf ou word) afin de valider la période d'essai des 45 jours. \\n\\nJe reprendrais contact avec vous pour faire un bilan de son implication et des tâches qui lui sont confiées durant son apprentissage. \\n\\nBien cordialement \\n\\n\\n \\n\\nM.DERRAR \\n\\nEnseignant en Architecture  \\n\\nLycée Professionnel Léon PAVIN - 241 Chemin du Trouillet - 07210 Chomérac \\n\\n06-66-94-98-05\\n\\nHISTORIQUE : tes dernières réponses à cet interlocuteur (de la plus récente à la plus ancienne)\\n--- Échange 1 (2026-07-07, objet : Re: Fiche Moulet Alizée) ---\\nBonjour,\\n\\nVous trouverez en pièce jointe le document signé.\\n\\nBonne réception.\\n\\nJe vous souhaite une très belle journée.\\n\\nCordialement,\\n\\nSelina Sanchez\\n\\n Am 01/07/2026, 13:53, Derrar Mustapha\\n<Mustapha.Derrar@ac-grenoble.fr> schrieb:\\n\\nRédige le brouillon de réponse.",{"lc":1,"type":"170","id":"171"},"claude-sonnet-4-6","https://api.anthropic.com",{},{"fetchOptions":"172"},{"lc":1,"type":"170","id":"173"},{"part":"174","childNodes":"175","type":"176","parameters":"177"},{"part":"178","type":"179","parameters":"180","encoding":"181","size":3455074,"disposition":"182","dispositionParameters":"183"},"7-C6akX6",{"name":"184","address":"185"},{"name":"184","address":"185"},{"name":"184","address":"185"},{"name":"120","address":"119"},["186"],"secret",["187"],{},["187"],"1",["188","189"],"multipart/alternative",{"boundary":"190"},"2","application/pdf",{"name":"191"},"base64","attachment",{"name":"191","filename":"191"},"Contact Ebanista","contact@ebanista.fr",{"text":"138"},"ANTHROPIC_API_KEY",{"part":"192","type":"193","parameters":"194","encoding":"195","size":942,"lineCount":38},{"part":"196","type":"197","parameters":"198","encoding":"195","size":5143,"lineCount":88},"gYkQ6oZK","Alizee.pdf","1.1","text/plain",{"charset":"199"},"quoted-printable","1.2","text/html",{"charset":"199"},"utf-8"]	20d95c4a-0c8e-40e3-8dea-1d5485e5ad05
552	{"id":"FqdcdqnhtYVRYTz6","name":"Tri mails - v.caufriez","nodes":[{"parameters":{"mailbox":"INBOX","postProcessAction":"nothing","format":"resolved","dataPropertyAttachmentsPrefixName":"attachment_","options":{}},"type":"n8n-nodes-base.emailReadImap","typeVersion":2.2,"position":[0,0],"id":"4acf197b-93b5-4ffa-894d-e8cf9068550e","name":"Email Trigger (IMAP)","credentials":{"imap":{"id":"wVKdbE1JQnIB1kzf","name":"IMAP - v.caufriez@ebanista.fr"}}},{"parameters":{"notice":"","promptType":"define","text":"=Voici un email à analyser :\\nExpéditeur : {{ $json.from.text }}\\nSujet : {{ $json.subject }}\\nContenu : {{ $json.text }}\\n","hasOutputParser":false,"needsFallback":false,"messages":{"messageValues":[{"type":"SystemMessagePromptTemplate","message":"Tu es un assistant qui trie les emails professionnels d'une entreprise de menuiserie/ébénisterie (EBANISTA). Pour chaque email, réponds UNIQUEMENT en JSON avec cette structure exacte :\\n{\\n  \\"categorie\\": \\"offre_fournisseur\\" | \\"confirmation_commande\\" | \\"prospects\\" | \\"suivi_client\\" | \\"administratif\\" | \\"litige\\" | \\"facturation\\" | \\"spam\\",\\n  \\"urgent\\": true ou false,\\n  \\"resume\\": \\"résumé en 2-3 lignes maximum\\",\\n  \\"auto_envoi_possible\\": true ou false,\\n  \\"reponse_requise\\": true ou false\\n}\\n\\nCatégories (avec exemples) :\\n- offre_fournisseur : devis, propositions commerciales ou catalogues reçus d'un fournisseur. Ex : \\"Devis panneaux MDF - validité 30 jours\\"\\n- confirmation_commande : accusés de réception ou confirmations d'une commande déjà passée à un fournisseur. Ex : \\"Confirmation de votre commande n°4521\\"\\n- prospects : demandes d'information ou de devis de particuliers/entreprises intéressés par nos services. Ex : \\"Devis pour cuisine sur mesure\\"\\n- suivi_client : échanges avec des clients déjà engagés sur un projet en cours. Ex : \\"Où en est mon meuble ?\\"\\n- administratif : courriers officiels, banque, assurance, impôts, RH. Ex : \\"Relevé bancaire disponible\\"\\n- litige : réclamation, mise en demeure, mention d'avocat/tribunal, forte insatisfaction client. TOUJOURS urgent=true et auto_envoi_possible=false.\\n- facturation : factures reçues ou envoyées, relances de paiement. Ex : \\"Facture n°2026-045\\"\\n- spam : newsletters, publicités, phishing évident, démarchage commercial non sollicité sans rapport avec l'activité.\\n\\nRègles d'urgence :\\n- Ne pas se fier au mot \\"urgent\\" dans le sujet s'il n'est pas justifié par le contenu réel (une simple question commerciale n'est pas urgente même si le sujet dit \\"urgent\\").\\n- Est urgent : litige (toujours), délai serré explicite (\\"réponse avant demain\\"), problème bloquant sur un chantier en cours, client insatisfait qui réclame.\\n\\nRègles auto_envoi_possible :\\n- true UNIQUEMENT pour : accusé de réception simple sans action requise, confirmation de rdv déjà validée, confirmation_commande (accusé fournisseur).\\n- false pour tout le reste, en particulier : offre_fournisseur, devis, facture, litige, toute demande nécessitant une réponse personnalisée ou une décision métier.\\n\\nRègles reponse_requise :\\n- true si l'expéditeur attend une vraie réponse rédigée de Valentin : question, demande de devis ou de prix, demande de rendez-vous ou de disponibilité, relance, réclamation, proposition à accepter ou refuser.\\n- false pour : spam, notifications et mails automatiques (y compris les réponses automatiques d'absence), accusés de réception et confirmations sans question, factures et relevés sans question, newsletters, mails reçus seulement en copie pour information.\\n\\nLe résumé doit être factuel et concis, sans reformuler tout l'email."}]},"batching":{}},"type":"@n8n/n8n-nodes-langchain.chainLlm","typeVersion":1.9,"position":[608,0],"id":"0c6fe25a-11e3-4c7e-b5ae-efd8a3629137","name":"Basic LLM Chain"},{"parameters":{"notice":"","model":{"__rl":true,"mode":"list","value":"claude-sonnet-4-6","cachedResultName":"Claude Sonnet 4.6"},"options":{}},"type":"@n8n/n8n-nodes-langchain.lmChatAnthropic","typeVersion":1.5,"position":[992,0],"id":"9d47d40d-f929-4681-ab5c-711d775c9e1d","name":"Anthropic Chat Model","credentials":{"anthropicApi":{"id":"FRxZizEr7zCaHHZp","name":"Claude API"}}},{"parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"const results = [];\\n\\nfor (const item of $input.all()) {\\n  const rawText = item.json.text;\\n  const match = rawText.match(/\\\\{[\\\\s\\\\S]*\\\\}/);\\n  const parsed = JSON.parse(match[0]);\\n  \\n  results.push({\\n    json: {\\n      categorie: parsed.categorie,\\n      urgent: parsed.urgent,\\n      resume: parsed.resume,\\n      auto_envoi_possible: parsed.auto_envoi_possible,\\n      reponse_requise: parsed.reponse_requise === true\\n    }\\n  });\\n}\\n\\nreturn results;\\n","notice":""},"type":"n8n-nodes-base.code","typeVersion":2,"position":[1120,144],"id":"10349273-435b-4320-b5fb-fbebf52de6a6","name":"Code in JavaScript"},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":3},"conditions":[{"id":"f22f7138-265f-46e1-8325-3ff0776b55a7","leftValue":"={{ $json.urgent }}","rightValue":"","operator":{"type":"boolean","operation":"true","singleValue":true}}],"combinator":"and"},"looseTypeValidation":false,"options":{}},"type":"n8n-nodes-base.if","typeVersion":2.3,"position":[1344,144],"id":"0b6b1958-7db2-468c-bf33-935de9103024","name":"If"},{"parameters":{"resource":"message","operation":"sendMessage","chatId":"8848139246","text":"={{ (\\"🚨 Mail urgent reçu\\\\n\\\\nDe : \\" + ($('Email Trigger (IMAP)').item.json.from.text) + \\"\\\\nCatégorie : \\" + ($json.categorie) + \\"\\\\n\\\\n\\" + ($json.resume) + \\"\\\\n\\").replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;') }}","replyMarkup":"inlineKeyboard","inlineKeyboard":{"rows":[{"row":{"buttons":[{"text":"↩️ Répondre","additionalFields":{"callback_data":"={{ 'rep:v:' + $('Email Trigger (IMAP)').item.json.attribu