imated":false},["92"],{"previousNode":"88","previousNodeOutput":0,"previousNodeRun":0},["93"],{"previousNode":"94","previousNodeOutput":0,"previousNodeRun":0},["95"],{"node":"96","runIndex":0},["97"],"Entrée sous-workflow",["98"],"Retrouver mes réponses précédentes",["99"],"Rédiger le brouillon",["100"],["101"],"Assembler le contexte",["102"],["103"],"Composer le brouillon",["104"],"Modèle Claude (brouillon)",{"json":"105","index":0,"pairedItem":"106"},{"json":"107","pairedItem":"108"},{"json":"109","pairedItem":"110"},{"json":"111"},{"json":"112"},{"json":"113","pairedItem":"114"},{"json":"115","pairedItem":"116"},{"json":"117","pairedItem":"118"},{"from_address":"119","from_name":"120","subject":"121","text":"122","date":"123","message_id":"124","resume":"125","categorie":"126"},{"item":0},{"seq":677,"uid":696,"modseq":"127","bodyStructure":"128","envelope":"129","id":"130","mailboxPath":"131","textContent":"132"},{"item":0},{"prompt":"133","historyCount":1},{"item":0},{"response":"134","tokenUsage":"135"},{"messages":"136","estimatedTokens":1686,"options":"137"},{"text":"138"},{"item":0},{"rfc822":"139","subject":"140","draftPreview":"138"},{"item":0},{"destination":"141","path":"141","seq":4,"uidValidity":"142","uid":5071},{"item":0},"aurelien.gabriel@fiducial.net","Aurélien Gabriel","Suite à demande téléphonique","Bonjour,\\n\\nJe fais suite à la demande concernant les repas, et les possibilités de pouvoir les indemniser, :\\n\\n-Nous pouvons garder les paniers repas du btp mais elles deviennent chargeable et imposable en totalité.\\n\\n- les tickets restaurant : vous êtes exonéré jusqu'à 7.32€ par tickets : ce qui donnerai une valeur faciale a 12.20€ si vous prenez en charge 60% ou 14.64€ si vous prenez 50 % en charge,\\nle reste est à la charge du salarié.\\n\\n-Il y a aussi une indemnité de repas qui existe à 7.50€ 100% exonérée : la contrainte est qu'il faut pouvoir justifié que le poste a certaine condition particulière comme (travail posté, horaires décalés,...)\\n\\non peut mettre les chèques cadeaux pour certains évènement listé ci-dessous, en 2026 jusqu’à 200€ exonéré par salarié  :\\nÉvénements éligibles et plafonds (200 € par événement)\\n\\n * *Noël* : 200 € pour le salarié + 200 € par enfant jusqu'à 16 ans\\n   révolus dans l'année.\\n * *Rentrée scolaire* : 200 € par enfant (jusqu'à 26 ans, scolarisé).\\n * *Naissance ou adoption* : 200 € par salarié (et par enfant concerné).\\n * *Mariage ou PACS* : 200 € par salarié.\\n * *Départ à la retraite* : 200 € par salarié.\\n * *Fête des Mères/ Fête des Pères* : 200 € par parent.\\n * *Sainte-Catherine/ Saint-Nicolas* : 200 € par salarié concerné\\n\\nCordialement,\\n\\nFIDUCIAL EXPERTISE \\t\\n\\tAurélien Gabriel \\t\\n\\t**Montelimar - Gestionnaire de paies \\t\\n\\taurelien.gabriel@fiducial.net \\t\\n\\tTel. Fixe 04 75 53 13 62 <tel:0475531362> \\t\\n\\t\\t\\n\\tChemin de Merly - 26200 Montelimar \\t\\n\\twww.fiducial.fr <http://www.fiducial.fr> \\t\\n\\n﻿\\n________________\\nCe message et les éventuels documents joints peuvent contenir des informations confidentielles. Au cas où il ne vous serait pas destiné, nous vous remercions de bien vouloir le supprimer et en aviser immédiatement l'expéditeur. Toute utilisation de ce message non conforme à sa destination, toute diffusion ou publication, totale ou partielle et quel qu'en soit le moyen est formellement interdite. Les communications sur internet n'étant pas sécurisées, l'intégrité de ce message n'est pas assurée et la société émettrice ne peut être tenue pour responsable de son contenu. ","2026-10-14T07:50:09.000Z","<76bda92c-7c12-6392-e107-02848eee01d3@fiducial.net>","Le gestionnaire de paie de Fiducial apporte des précisions sur les options d'indemnisation des repas salariés : paniers repas BTP (imposables), tickets restaurant (exonération jusqu'à 7,32€), indemnité repas à 7,50€ (sous conditions), et chèques cadeaux exonérés jusqu'à 200€ par événement en 2026.","administratif","1553",{"childNodes":"143","type":"144","parameters":"145"},{"date":"146","subject":"147","from":"148","sender":"149","replyTo":"150","to":"151","inReplyTo":"152","messageId":"153"},"58612c31518d12aeab9c420d79acb88e","Sent","Bonjour Aurélien, \\r\\n\\r\\nVous trouverez-ci joint le contrat de Mr Guironnet \\r\\n\\r\\nCordialement, \\r\\n\\r\\nCaufriez Valentin \\r\\n\\r\\n---------- Message transféré ---------\\r\\nDe : CFA Greta Drôme Ardèche <cfa@greta-0726.fr>\\r\\nDate : 2026-10-08T16:09:02.000+02:00\\r\\nSujet : CONTRAT - GUIRONNET QUENTIN\\r\\nÀ : Ebanista <contact@ebanista.fr>\\r\\n\\r\\nBonjour, \\r\\n\\r\\nVeuillez trouver ci joint le contrat signé de l'apprenti GUIRONNET\\r\\nQUENTIN.\\r\\nBonne réception\\r\\n\\r\\nBien cordialement\\r\\nSOPHYS Justine\\r\\nAssistante de formation et d'apprentissage-- \\r\\n\\r\\nSERVICE APPRENTISSAGE\\r\\n\\r\\nGRETA Ardèche Drôme  \\r\\n04 75 82 37 90\\r\\n\\r\\ngreta-ardechedrome.fr\\r\\n\\r\\n [https://greta-ardechedrome.fr/formations-en-alternance]\\r\\n\\r\\n","MAIL REÇU\\nDe : Aurélien Gabriel <aurelien.gabriel@fiducial.net>\\nObjet : Suite à demande téléphonique\\nDate : 2026-10-14T07:50:09.000Z\\nRésumé (assistant de tri) : Le gestionnaire de paie de Fiducial apporte des précisions sur les options d'indemnisation des repas salariés : paniers repas BTP (imposables), tickets restaurant (exonération jusqu'à 7,32€), indemnité repas à 7,50€ (sous conditions), et chèques cadeaux exonérés jusqu'à 200€ par événement en 2026.\\n\\nContenu :\\nBonjour,\\n\\nJe fais suite à la demande concernant les repas, et les possibilités de pouvoir les indemniser, :\\n\\n-Nous pouvons garder les paniers repas du btp mais elles deviennent chargeable et imposable en totalité.\\n\\n- les tickets restaurant : vous êtes exonéré jusqu'à 7.32€ par tickets : ce qui donnerai une valeur faciale a 12.20€ si vous prenez en charge 60% ou 14.64€ si vous prenez 50 % en charge,\\nle reste est à la charge du salarié.\\n\\n-Il y a aussi une indemnité de repas qui existe à 7.50€ 100% exonérée : la contrainte est qu'il faut pouvoir justifié que le poste a certaine condition particulière comme (travail posté, horaires décalés,...)\\n\\non peut mettre les chèques cadeaux pour certains évènement listé ci-dessous, en 2026 jusqu’à 200€ exonéré par salarié  :\\nÉvénements éligibles et plafonds (200 € par événement)\\n\\n * *Noël* : 200 € pour le salarié + 200 € par enfant jusqu'à 16 ans\\n   révolus dans l'année.\\n * *Rentrée scolaire* : 200 € par enfant (jusqu'à 26 ans, scolarisé).\\n * *Naissance ou adoption* : 200 € par salarié (et par enfant concerné).\\n * *Mariage ou PACS* : 200 € par salarié.\\n * *Départ à la retraite* : 200 € par salarié.\\n * *Fête des Mères/ Fête des Pères* : 200 € par parent.\\n * *Sainte-Catherine/ Saint-Nicolas* : 200 € par salarié concerné\\n\\nCordialement,\\n\\nFIDUCIAL EXPERTISE \\t\\n\\tAurélien Gabriel \\t\\n\\t**Montelimar - Gestionnaire de paies \\t\\n\\taurelien.gabriel@fiducial.net \\t\\n\\tTel. Fixe 04 75 53 13 62 <tel:0475531362> \\t\\n\\t\\t\\n\\tChemin de Merly - 26200 Montelimar \\t\\n\\twww.fiducial.fr <http://www.fiducial.fr> \\t\\n\\n﻿\\n________________\\nCe message et les éventuels documents joints peuvent contenir des informations confidentielles. Au cas où il ne vous serait pas destiné, nous vous remercions de bien vouloir le supprimer et en aviser immédiatement l'expéditeur. Toute utilisation de ce message non conforme à sa destination, toute diffusion ou publication, totale ou partielle et quel qu'en soit le moyen est formellement interdite. Les communications sur internet n'étant pas sécurisées, l'intégrité de ce message n'est pas assurée et la société émettrice ne peut être tenue pour responsable de son contenu.\\n\\nHISTORIQUE : tes dernières réponses à cet interlocuteur (de la plus récente à la plus ancienne)\\n--- Échange 1 (2026-10-09, objet : Fw: CONTRAT - GUIRONNET QUENTIN) ---\\nBonjour Aurélien, \\n\\nVous trouverez-ci joint le contrat de Mr Guironnet \\n\\nCordialement, \\n\\nCaufriez Valentin \\n\\n---------- Message transféré ---------\\n\\nRédige le brouillon de réponse.",{"generations":"154"},{"completionTokens":101,"promptTokens":2222,"totalTokens":2323},["155"],{"anthropic_api_key":"156","model":"157","anthropic_api_url":"158","max_tokens":16384,"invocation_kwargs":"159","client_options":"160","streaming":false,"temperature":0.4,"api_key":"161"},"Bonjour Aurélien,\\n\\nMerci pour ces précisions concernant les différentes options d'indemnisation des repas.\\n\\nNous allons étudier les possibilités qui s'offrent à nous et reviendrons vers vous prochainement avec notre décision.\\n\\nJe vous remercie par avance pour votre disponibilité.\\n\\nCordialement,\\n\\n[À COMPLÉTER : signature]","From: Ebanista <contact@ebanista.fr>\\r\\nTo: =?UTF-8?B?QXVyw6lsaWVuIEdhYnJpZWw=?= <aurelien.gabriel@fiducial.net>\\r\\nSubject: =?UTF-8?B?UmU6IFN1aXRlIA==?=\\r\\n =?UTF-8?B?w6AgZGVtYW5kZSA=?=\\r\\n =?UTF-8?B?dMOpbMOpcGhvbmlx?=\\r\\n =?UTF-8?B?dWU=?=\\r\\nDate: Wed, 14 Oct 2026 07:50:24 +0000\\r\\nMessage-ID: <draft-1791964224017-9mysefcq@ebanista.fr>\\r\\nIn-Reply-To: <76bda92c-7c12-6392-e107-02848eee01d3@fiducial.net>\\r\\nReferences: <76bda92c-7c12-6392-e107-02848eee01d3@fiducial.net>\\r\\nMIME-Version: 1.0\\r\\nContent-Type: text/plain; charset=UTF-8\\r\\nContent-Transfer-Encoding: base64\\r\\n\\r\\nQm9uam91ciBBdXLDqWxpZW4sDQoNCk1lcmNpIHBvdXIgY2VzIHByw6ljaXNpb25zIGNvbmNlcm5h\\r\\nbnQgbGVzIGRpZmbDqXJlbnRlcyBvcHRpb25zIGQnaW5kZW1uaXNhdGlvbiBkZXMgcmVwYXMuDQoN\\r\\nCk5vdXMgYWxsb25zIMOpdHVkaWVyIGxlcyBwb3NzaWJpbGl0w6lzIHF1aSBzJ29mZnJlbnQgw6Ag\\r\\nbm91cyBldCByZXZpZW5kcm9ucyB2ZXJzIHZvdXMgcHJvY2hhaW5lbWVudCBhdmVjIG5vdHJlIGTD\\r\\nqWNpc2lvbi4NCg0KSmUgdm91cyByZW1lcmNpZSBwYXIgYXZhbmNlIHBvdXIgdm90cmUgZGlzcG9u\\r\\naWJpbGl0w6kuDQoNCkNvcmRpYWxlbWVudCwNCg0KW8OAIENPTVBMw4lURVIgOiBzaWduYXR1cmVd\\r\\nDQoNCg0KTGUgMTQgb2N0b2JyZSAyMDI2IMOgIDA5OjUwLCBBdXLDqWxpZW4gR2FicmllbCA8YXVy\\r\\nZWxpZW4uZ2FicmllbEBmaWR1Y2lhbC5uZXQ+IGEgw6ljcml0IDoNCj4gQm9uam91ciwNCj4gDQo+\\r\\nIEplIGZhaXMg