imated":false},["92"],{"previousNode":"88","previousNodeOutput":0,"previousNodeRun":0},["93"],{"previousNode":"94","previousNodeOutput":0,"previousNodeRun":0},["95"],{"node":"96","runIndex":0},["97"],"Entrée sous-workflow",["98","99","100"],"Retrouver mes réponses précédentes",["101"],"Rédiger le brouillon",["102"],["103"],"Assembler le contexte",["104"],["105"],"Composer le brouillon",["106"],"Modèle Claude (brouillon)",{"json":"107","index":0,"pairedItem":"108"},{"json":"109","pairedItem":"110"},{"json":"111","pairedItem":"112"},{"json":"113","pairedItem":"114"},{"json":"115","pairedItem":"116"},{"json":"117"},{"json":"118"},{"json":"119","pairedItem":"120"},{"json":"121","pairedItem":"122"},{"json":"123","pairedItem":"124"},{"from_address":"125","from_name":"126","subject":"127","text":"128","date":"129","message_id":"130","resume":"131","categorie":"132"},{"item":0},{"seq":430,"uid":435,"modseq":"133","bodyStructure":"134","envelope":"135","id":"136","mailboxPath":"137","textContent":"138"},{"item":0},{"seq":440,"uid":445,"modseq":"139","bodyStructure":"140","envelope":"141","id":"142","mailboxPath":"137","textContent":"143"},{"item":0},{"seq":640,"uid":656,"modseq":"144","bodyStructure":"145","envelope":"146","id":"147","mailboxPath":"137","textContent":"148"},{"item":0},{"prompt":"149","historyCount":3},{"item":0},{"response":"150","tokenUsage":"151"},{"messages":"152","estimatedTokens":2233,"options":"153"},{"text":"154"},{"item":0},{"rfc822":"155","subject":"156","draftPreview":"154"},{"item":0},{"destination":"157","path":"157","seq":7,"uidValidity":"158","uid":5090},{"item":0},"raffi.malikian@arlu.be","Raffi Malikian","ARLU PARTENAIRE DIVINA","\\nBonjour Valentin,\\n\\nComme évoqué lors de mon passage, je te propose de devenir « Partenaire Divina ».\\n\\n  *   Compte en direct sur la Divina\\n  *   Remise 45 % sur notre configurateur Arlu Connect\\n  *   Ebanista sera sur notre carte de France en tant que partenaire\\n  *   Transmission des demandes sur to