\\" style=\\"text-align: justify;\\">&nbsp;</p>\\n<p class=\\"MsoNormal\\" style=\\"text-align: justify;\\"><span style=\\"color: #000000;\\">📅 <b>Offre valable jusqu&#8217;au 31 d&#233;cembre 2026</b>, dans la limite des disponibilit&#233;s.</span></p></div></td></tr></table></td></tr></table></td><td width=\\"10\\"></td></tr><tr height=\\"10\\"><td colSpan=\\"3\\"></td></tr></table></td><td width=\\"15\\"></td></tr></table></td></tr></table><!--[if (mso) | (IE)]></td></tr></table><![endif]--></td></tr><tr height=\\"15\\"><td></td></tr></table><table class=\\"LayoutRow lt\\" border=\\"0\\" cellPadding=\\"0\\" cellSpacing=\\"0\\" width=\\"100%\\" style=\\"width:100%\\"><tr><td valign=\\"top\\"><!--[if (mso) | (IE)]><table width=\\"100%\\" border=\\"0\\" cellPadding=\\"0\\" cellSpacing=\\"0\\" style=\\"mso-table-lspace:0pt;mso-table-rspace:0pt;border-collapse:collapse;padding-top:0;padding-bottom:0;padding-left:0;padding-right:0;\\"><tr><td width=\\"100%\\" valign=\\"top\\"><![endif]--><table class=\\"LayoutColumn col-sm-12 lt\\" border=\\"0\\" cellPadding=\\"0\\" cellSpacing=\\"0\\" width=\\"100%\\"><tr><td valign=\\"top\\"><table class=\\"lt\\" border=\\"0\\" cellPadding=\\"0\\" cellSpacing=\\"0\\" width=\\"100%\\"><tr><td valign=\\"top\\"><table class=\\"LayoutColumnContainer lt\\" border=\\"0\\" cellPadding=\\"0\\" cellSpacing=\\"0\\" width=\\"100%\\" style=\\"width:100%\\"><tr height=\\"10\\"><td colSpan=\\"3\\"></td></tr><tr><td width=\\"10\\"></td><td valign=\\"top\\"><table class=\\"LayoutBlock LayoutBlock-Text lt\\" border=\\"0\\" cellPadding=\\"0\\" cellSpacing=\\"0\\" width=\\"100%\\" style=\\"width:100%\\"><tr><td valign=\\"top\\"><table class=\\"lt\\" border=\\"0\\" cellPadding=\\"0\\" cellSpacing=\\"0\\" width=\\"100%\\" align=\\"left\\" style=\\"word-break:break-word;color:#000000;text-align:left;word-wrap:break-word;width:100%\\"><tr><td valign=\\"top\\"><div class=\\"j6jay0cv\\"><p><span style=\\"font-family: arial, helvetica neue, helvetica, sans-se