3d3cudG90YWxlbmVyZ2llcy5mci9ncm91cGUvaGlzdG9yaXF1ZS1jb25kaXRpb25zLWdlbmVyYWxlcy1kZS12ZW50ZQ?b=1\\">https://1p58t.mjt.lu/lnk/AVIAAKeD_REAAAAAAAAABDb7-7oAAYKJDGsAAAAAADTpaQBq2bgznb1ItJHdQzSof_FlQtT5mwAI1Ko/0/jUc1WRQnN-36z7FTBvq7vg/aHR0cHM6Ly93d3cudG90YWxlbmVyZ2llcy5mci9ncm91cGUvaGlzdG9yaXF1ZS1jb25kaXRpb25zLWdlbmVyYWxlcy1kZS12ZW50ZQ?b=1</a><br/>[<a href=\\"https://1p58t.mjt.lu/oo/AVIAAKeD_REAAAAAAAAABDb7-7oAAYKJDGsAAAAAADTpaQBq2bgznb1ItJHdQzSof_FlQtT5mwAI1Ko/9eff86c7/e.gif\\">https://1p58t.mjt.lu/oo/AVIAAKeD_REAAAAAAAAABDb7-7oAAYKJDGsAAAAAADTpaQBq2bgznb1ItJHdQzSof_FlQtT5mwAI1Ko/9eff86c7/e.gif</a>]<br/><a href=\\"https://1p58t.mjt.lu/lnk/AVIAAKeD_REAAAAAAAAABDb7-7oAAYKJDGsAAAAAADTpaQBq2bgznb1ItJHdQzSof_FlQtT5mwAI1Ko/0/jUc1WRQnN-36z7FTBvq7vg/aHR0cHM6Ly93d3cudG90YWxlbmVyZ2llcy5mci9ncm91cGUvaGlzdG9yaXF1ZS1jb25kaXRpb25zLWdlbmVyYWxlcy1kZS12ZW50ZQ?b=3\\">https://1p58t.mjt.lu/lnk/AVIAAKeD_REAAAAAAAAABDb7-7oAAYKJDGsAAAAAADTpaQBq2bgznb1ItJHdQzSof_FlQtT5mwAI1Ko/0/jUc1WRQnN-36z7FTBvq7vg/aHR0cHM6Ly93d3cudG90YWxlbmVyZ2llcy5mci9ncm91cGUvaGlzdG9yaXF1ZS1jb25kaXRpb25zLWdlbmVyYWxlcy1kZS12ZW50ZQ?b=3</a></p><p>Pour toutes questions relatives au renouvellement de votre contrat, votre<br/>service client reste &agrave; votre enti&egrave;re disposition.</p><p>L&rsquo;&eacute;quipe Renouvellement de TotalEnergies</p><p><a href=\\"https://1p58t.mjt.lu/lnk/AVIAAKeD_REAAAAAAAAABDb7-7oAAYKJDGsAAAAAADTpaQBq2bgznb1ItJHdQzSof_FlQtT5mwAI1Ko/0/jUc1WRQnN-36z7FTBvq7vg/aHR0cHM6Ly93d3cudG90YWxlbmVyZ2llcy5mci9ncm91cGUvaGlzdG9yaXF1ZS1jb25kaXRpb25zLWdlbmVyYWxlcy1kZS12ZW50ZQ?b=1\\">https://1p58t.mjt.lu/lnk/AVIAAKeD_REAAAAAAAAABDb7-7oAAYKJDGsAAAAAADTpaQBq2bgznb1ItJHdQzSof_FlQtT5mwAI1Ko/0/jUc1WRQnN-36z7FTBvq7vg/aHR0cHM6Ly93d3cudG90YWxlbmVyZ2llcy5mci9ncm91cGUvaGlzdG9yaXF1ZS1jb25kaXRpb25zLWdlbmVyYWxlcy1kZS12ZW50ZQ?b=1</a><br/>[<a href=\\"https://1p58t.mjt.lu/oo/AVIAAKeD_REAAAAAAAAABDb7-7oAAYKJDGsAAAAAADTpaQBq2bgznb1ItJHdQzSof_FlQtT5mwAI1Ko/9eff86c7/e.gif\\">https://1p58t.mjt.lu/oo/AVIAAKeD_REAAAAAAAAABDb7-7oAAYKJDGsAAAAAADTpaQBq2bgznb1ItJHdQzSof_FlQtT5mwAI1Ko/9eff86c7/e.gif</a>]<br/><a href=\\"https://1p58t.mjt.lu/lnk/AVIAAKeD_REAAAAAAAAABDb7-7oAAYKJDGsAAAAAADTpaQBq2bgznb1ItJHdQzSof_FlQtT5mwAI1Ko/0/jUc1WRQnN-36z7FTBvq7vg/aHR0cHM6Ly93d3cudG90YWxlbmVyZ2llcy5mci9ncm91cGUvaGlzdG9yaXF1ZS1jb25kaXRpb25zLWdlbmVyYWxlcy1kZS12ZW50ZQ?b=3\\">https://1p58t.mjt.lu/lnk/AVIAAKeD_REAAAAAAAAABDb7-7oAAYKJDGsAAAAAADTpaQBq2bgznb1ItJHdQzSof_FlQtT5mwAI1Ko/0/jUc1WRQnN-36z7FTBvq7vg/aHR0cHM6Ly93d3cudG90YWxlbmVyZ2llcy5mci9ncm91cGUvaGlzdG9yaXF1ZS1jb25kaXRpb25zLWdlbmVyYWxlcy1kZS12ZW50ZQ?b=3</a></p><p>(1)&nbsp;Les tarifs HT du kWh indiqu&eacute;s ne tiennent pas compte d&rsquo;&eacute;ventuelles<br/>r&eacute;ductions li&eacute;es aux dispositifs d&rsquo;aides mis en place par le gouvernement ou<br/>TotalEnergies. L&rsquo;&eacute;volution pr&eacute;sent&eacute;e en % repr&eacute;sente l&rsquo;&eacute;cart entre les anciens<br/>et les nouveaux tarifs HT pour le kWh et l&rsquo;abonnement. Cette &eacute;volution est<br/>calcul&eacute;e en fonction de vos caract&eacute;ristiques techniques (option tarifaire et<br/>puissance souscrite) et pour le p&eacute;rim&egrave;tre tels que d&eacute;finis dans votre Bulletin<br/>de souscription.</p><p>(2) L&rsquo;acheminement (transport et distribution) est refactur&eacute; &agrave; l&apos;euro pr&egrave;s selon<br/>la r&eacute;glementation en vigueur et le m&eacute;canisme de capacit&eacute; est factur&eacute; de plein<br/>droit en application des r&egrave;gles l&eacute;gislatives et r&egrave;glementaires selon la formule<br/>d&eacute;finie par TotalEnergies dans vos Conditions G&eacute;n&eacute;rales de Vente.</p><p>(3) Budget annuel estim&eacute; &agrave; titre indicatif, ne constitue pas un engagement<br/>contractuel. Le nouveau budget annuel pr&eacute;visionnel est calcul&eacute; sur la base des<br/>tarifs HT applicables &agrave; compter du 01/01/2027 et l&rsquo;ancien budget annuel<br/>pr&eacute;visionnel est calcul&eacute; sur la base des tarifs HT applicables jusqu&rsquo;au<br/>31/12/2026, sans tenir compte d&rsquo;&eacute;ventuelles r&eacute;ductions li&eacute;es aux dispositifs<br/>d&rsquo;aides mis en place par le gouvernement ou TotalEnergies. L&rsquo;ancien et le<br/>nouveau budget annuel pr&eacute;visionnel sont exprim&eacute;s en TTC dans la mesure o&ugrave; ils<br/>comprennent &eacute;galement les &eacute;ventuelles taxes et contributions ainsi que la part<br/>acheminement et la part m&eacute;canisme de capacit&eacute; en vigueur &agrave; la date d&rsquo;envoi du<br/>pr&eacute;sent courrier et qui sont susceptibles d&rsquo;&eacute;voluer conform&eacute;ment &agrave; vos<br/>Conditions G&eacute;n&eacute;rales de Vente. L&rsquo;&eacute;volution pr&eacute;sent&eacute;e en % repr&eacute;sente l&rsquo;&eacute;cart<br/>entre les deux budgets annuels pr&eacute;visionnels. Cette &eacute;volution est calcul&eacute;e en<br/>fonction de vos caract&eacute;ristiques techniques (option tarifaire et puissance<br/>souscrite) et pour le p&eacute;rim&egrave;tre tels que d&eacute;finis dans votre Bulletin de<br/>souscription.</p><p>(4) La consommation annuelle pr&eacute;visionnelle est d&eacute;termin&eacute;e par TotalEnergies &agrave;<br/>partir de l&rsquo;historique mensuel de vos consommations ant&eacute;rieures transmises par<br/>Enedis et/ou des auto rel&egrave;ves que vous nous auriez transmises pour ce compteur.</p><p>(5) cf. article &laquo; Indemnit&eacute;s de r&eacute;siliation anticip&eacute;e &raquo; des CGV applicables &agrave;<br/>votre nouvelle offre &agrave; compter du 01/01/2027. Jusqu&rsquo;au 31/12/2026, en cas de<br/>r&eacute;siliation anticip&eacute;e, ce sont vos anciennes Conditions G&eacute;n&eacute;rales de Vente (CGV)<br/>qui seront appliqu&eacute;es pour le calcul de vos frais de r&eacute;siliation.</p><p><a href=\\"https://1p58t.mjt.lu/lnk/AVIAAKeD_REAAAAAAAAABDb7-7oAAYKJDGsAAAAAADTpaQBq2bgznb1ItJHdQzSof_FlQtT5mwAI1Ko/0/jUc1WRQnN-36z7FTBvq7vg/aHR0cHM6Ly93d3cudG90YWxlbmVyZ2llcy5mci9ncm91cGUvaGlzdG9yaXF1ZS1jb25kaXRpb25zLWdlbmVyYWxlcy1kZS12ZW50ZQ?b=1\\">https://1p58t.mjt.lu/lnk/AVIAAKeD_REAAAAAAAAABDb7-7oAAYKJDGsAAAAAADTpaQBq2bgznb1ItJHdQzSof_FlQtT5mwAI1Ko/0/jUc1WRQnN-36z7FTBvq7vg/aHR0cHM6Ly93d3cudG90YWxlbmVyZ2llcy5mci9ncm91cGUvaGlzdG9yaXF1ZS1jb25kaXRpb25zLWdlbmVyYWxlcy1kZS12ZW50ZQ?b=1</a><br/>[<a href=\\"https://1p58t.mjt.lu/oo/AVIAAKeD_REAAAAAAAAABDb7-7oAAYKJDGsAAAAAADTpaQBq2bgznb1ItJHdQzSof_FlQtT5mwAI1Ko/9eff86c7/e.gif\\">https://1p58t.mjt.lu/oo/AVIAAKeD_REAAAAAAAAABDb7-7oAAYKJDGsAAAAAADTpaQBq2bgznb1ItJHdQzSof_FlQtT5mwAI1Ko/9eff86c7/e.gif</a>]<br/><a href=\\"https://1p58t.mjt.lu/lnk/AVIAAKeD_REAAAAAAAAABDb7-7oAAYKJDGsAAAAAADTpaQBq2bgznb1ItJHdQzSof_FlQtT5mwAI1Ko/0/jUc1WRQnN-36z7FTBvq7vg/aHR0cHM6Ly93d3cudG90YWxlbmVyZ2llcy5mci9ncm91cGUvaGlzdG9yaXF1ZS1jb25kaXRpb25zLWdlbmVyYWxlcy1kZS12ZW50ZQ?b=3\\">https://1p58t.mjt.lu/lnk/AVIAAKeD_REAAAAAAAAABDb7-7oAAYKJDGsAAAAAADTpaQBq2bgznb1ItJHdQzSof_FlQtT5mwAI1Ko/0/jUc1WRQnN-36z7FTBvq7vg/aHR0cHM6Ly93d3cudG90YWxlbmVyZ2llcy5mci9ncm91cGUvaGlzdG9yaXF1ZS1jb25kaXRpb25zLWdlbmVyYWxlcy1kZS12ZW50ZQ?b=3</a></p>","Message important- Votre renouvellement de contrat","2026-10-22T07:14:57.000Z",{"value":"218","html":"219","text":"220"},{"value":"221","html":"222","text":"174"},"<0d1776c0.AVIAAKeD_REAAAAAAAAABDb7-7oAAYKJDGsAAAAAADTpaQBq2bgz@mailjet.com>",{"uid":1490},{"generations":"223"},{"completionTokens":169,"promptTokens":8661,"totalTokens":8830},["224"],{"anthropic_api_key":"225","model":"226","anthropic_api_url":"227","max_tokens":16384,"invocation_kwargs":"228","client_options":"229","streaming":false,"api_key":"230"},"```json\\n{\\n  \\"categorie\\": \\"administratif\\",\\n  \\"urgent\\": false,\\n  \\"resume\\": \\"TotalEnergies informe du renouvellement automatique du contrat électricité Horizon C5 - 12 mois à partir du 01/01/2027, avec une hausse du prix du kWh de +29,1% (0,0936 → 0,1209 € HT). Aucune action requise pour accepter ; un changement de fournisseur avant le 01/01/2027 est nécessaire pour refuser.\\",\\n  \\"auto_envoi_possible\\